// An acknowledgement is a decision, so it is written when the reviewer makes
// it rather than being carried along until approval. Approval writes its own
// summary row with the full acknowledged_refs list; this row records the
// individual moment, so the trail shows a reviewer who acknowledged and then
// walked away — the case the approval row can never capture.
const body = $('Webhook acknowledge').first().json.body || {};

const reportId = (body.report_id || '').trim();
const employeeId = (body.employee_id || '').trim();
const reviewer = (body.reviewer || '').trim();
const pointRef = (body.point_ref || '').trim();
const flagType = (body.flag_type || '').trim();

if (!reportId || !employeeId || !reviewer || !pointRef) {
  return [{ json: { __http_status: 400, ok: false, error: 'invalid_acknowledgement', detail: 'report_id, employee_id, reviewer and point_ref are all required' } }];
}
if (!/^\w+\[\d+\]$/.test(pointRef)) {
  return [{ json: { __http_status: 400, ok: false, error: 'invalid_point_ref', detail: 'point_ref must look like growth_areas[1]' } }];
}

return [{ json: {
  __http_status: 200,
  ok: true,
  report_id: reportId,
  employee_id: employeeId,
  reviewer,
  diff: JSON.stringify({ acknowledged_refs: [pointRef], flag_type: flagType || null })
} }];
